<?php
// Isolated real schema, no production database or document service.
$path=sys_get_temp_dir().'/oddworks-inventory-'.bin2hex(random_bytes(8)).'.sqlite';
putenv('PROJECTFLOW_DB_PATH='.$path);putenv('PROJECTFLOW_ADMIN_PASSWORD=inventory-test-only');
register_shutdown_function(static function()use($path){foreach([$path,$path.'-wal',$path.'-shm'] as $p)if(is_file($p))unlink($p);});
ob_start();require __DIR__.'/../install/init_database.php';ob_end_clean();
require_once __DIR__.'/../includes/schema.php';runSchemaMigrations();
require_once __DIR__.'/../includes/stock/catalogue.php';$db=getDB();
function catalogCheck(bool $ok,string $message):void {if(!$ok)throw new RuntimeException($message);}
function catalogCommand(string $action,array $p):?int {global $db;$db->exec('BEGIN IMMEDIATE');try{$id=invCommand($db,$action,$p,1,true);$db->exec('COMMIT');return $id;}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}}
function catalogReject(string $action,array $p):void {global $db;$before=invRevision($db);try{catalogCommand($action,$p);}catch(InvalidArgumentException|PDOException $e){catalogCheck($before===invRevision($db),'Écriture partielle après rejet : '.$action);return;}throw new RuntimeException('Action invalide acceptée : '.$action);}
$category=catalogCommand('category_save',['nom'=>'Capteurs','description'=>'Mesure']);
$location=catalogCommand('location_save',['nom'=>'Bac A','parent_id'=>'','description'=>'ESD','type'=>'Bac']);
$struct=catalogCommand('location_save',['nom'=>'Magasin','structurel'=>true]);
$part=['designation'=>'Capteur de température','reference_fabricant'=>'TEST-01','fabricant'=>'Marque A','categorie_id'=>$category,'inventory_mode'=>'lot','unite'=>'u','quantite_min'=>2,'flags'=>['purchasable'=>true,'component'=>true]];
$id=catalogCommand('article_save',$part);
catalogReject('article_save',$part);$other=catalogCommand('article_save',array_replace($part,['fabricant'=>'Marque B']));
catalogCheck($id!==$other,'Couple fabricant / référence');
$variant=catalogCommand('article_save',array_replace($part,['reference_fabricant'=>'TEST-02','inventory_parent'=>$id]));
catalogCheck(invAvailable($db,$variant)===0.0,'Une variante démarre sans stock');
catalogReject('category_delete',['id'=>$category]);
$receipt=['article_id'=>$id,'location_id'=>$location,'quantity'=>10,'trace'=>'LOT-A','cost'=>2.8,'received'=>'2026-10-28','quality'=>'pending'];
catalogReject('stock_create',array_replace($receipt,['location_id'=>$struct]));
catalogReject('stock_create',array_replace($receipt,['received'=>'2026-02-30']));
$lot=catalogCommand('stock_create',$receipt);
catalogCheck(invAvailable($db,$id)===0.0,'Un lot à contrôler reste indisponible');
$record=array_values(array_filter(invRecords($db),fn($r)=>(int)$r['article_id']===$id))[0];
catalogCheck((float)$record['quantity']===10.0,'Stock physique en attente de contrôle');
catalogReject('stock_create',$receipt);
catalogCommand('quality',['article_id'=>$id,'key'=>$record['key'],'quality'=>'accepted','comment'=>'Conforme au contrôle visuel']);
catalogCheck(invAvailable($db,$id)===10.0,'Acceptation rend le lot disponible');
invRun($db,"INSERT INTO projets(nom,createur_id) VALUES('Projet test',1)");$pid=(int)$db->lastInsertId();
$res=catalogCommand('reserve',['article_id'=>$id,'projet_id'=>$pid,'location_id'=>$location,'quantity'=>4]);
catalogCheck(invAvailable($db,$id)===6.0,'Réservation réduit le disponible');
catalogReject('reserve',['article_id'=>$id,'projet_id'=>$pid,'location_id'=>$location,'quantity'=>7]);
catalogReject('quality',['article_id'=>$id,'key'=>$record['key'],'quality'=>'rejected','comment'=>'Réservé']);
catalogReject('stock_out',['article_id'=>$id,'key'=>$record['key'],'quantity'=>7,'comment'=>'Prototype']);
catalogCommand('stock_out',['article_id'=>$id,'key'=>$record['key'],'quantity'=>2,'comment'=>'Essai prototype']);
catalogCheck(invAvailable($db,$id)===4.0,'Sortie et réservations cohérentes');
catalogCommand('release',['id'=>$res,'comment'=>'Projet suspendu']);
catalogCommand('quality',['article_id'=>$id,'key'=>$record['key'],'quality'=>'quarantine','comment'=>'Analyse complémentaire']);
catalogCheck(invAvailable($db,$id)===0.0,'Quarantaine bloque le restant');
catalogCommand('stock_create',array_replace($receipt,['trace'=>'LOT-B','cost'=>2.1,'quality'=>'accepted','quantity'=>3]));
$st=invState($db);$a=array_values(array_filter($st['articles'],fn($a)=>(int)$a['id']===$id))[0];
catalogCheck((float)$a['price']===2.8&&(float)$a['physical']===11.0&&(float)$a['available']===3.0,'Maximum reçu, physique et disponible');
catalogReject('location_save',['id'=>$location,'nom'=>'Bac A','structurel'=>true]);
catalogReject('location_save',['id'=>$struct,'nom'=>'Magasin','parent_id'=>$struct]);
catalogCommand('parameter_save',['article_id'=>$id,'nom'=>'Tension','valeur'=>'3.3','unite'=>'V']);
catalogCommand('parameter_save',['article_id'=>$other,'nom'=>'Tension','valeur'=>'5','unite'=>'V']);
catalogReject('parameter_save',['article_id'=>$id,'nom'=>' tension ','valeur'=>'12']);
catalogCommand('lock',['article_id'=>$id]);catalogReject('parameter_save',['article_id'=>$id,'nom'=>'Courant','valeur'=>'1']);catalogCommand('lock',['article_id'=>$id]);
$serial=catalogCommand('article_save',array_replace($part,['reference_fabricant'=>'SER-01','inventory_mode'=>'serial']));
$sr=array_replace($receipt,['article_id'=>$serial,'quantity'=>1,'trace'=>'SN-0001','quality'=>'accepted']);
catalogCommand('stock_create',$sr);catalogReject('stock_create',$sr);catalogReject('stock_create',array_replace($sr,['trace'=>'SN-0002','quantity'=>2]));
$maker=catalogCommand('manufacturer_save',['article_id'=>$id,'company'=>'Fabricant A','reference'=>'A-01']);
catalogCommand('supplier_save',['article_id'=>$id,'company'=>'Distributeur','manufacturer_id'=>$maker,'sku'=>'SKU-1','pack_quantity'=>100,'prix_ht'=>0.05,'actif'=>true]);
catalogReject('supplier_save',['article_id'=>$other,'company'=>'Distributeur','manufacturer_id'=>$maker,'sku'=>'SKU-2','pack_quantity'=>1]);
catalogReject('manufacturer_save',['article_id'=>$id,'company'=>'Fabricant A','reference'=>'BAD','lien'=>'javascript:alert(1)']);
$before=invRevision($db);inventorySchema($db);catalogCheck($before===invRevision($db),'Migration rejouée sans altération');
catalogCheck(count(invRows($db,'SELECT * FROM inventory_history'))>10,'Historique conservé');
echo "OK : catalogue natif, identité fabricant, variantes, catégories, emplacements, paramètres, stock, contrôles, réservations, prix, séries, verrous et atomicité\n";
